class Solution:
    def findPaths(self, m: int, n: int, maxMove: int, startRow: int, startColumn: int) -> int:
        if maxMove == 0:
            return 0

        MOD = 10**9 + 7

        # dp[r][c] stores the number of ways to reach cell (r, c) after `k` moves
        dp = [[0] * n for _ in range(m)]
        dp[startRow][startColumn] = 1

        total_paths = 0

        # Directions for movement: up, down, left, right
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        # Iterate for each move from 1 to maxMove
        for moves in range(1, maxMove + 1):
            next_dp = [[0] * n for _ in range(m)]

            # Iterate through each cell in the grid
            for r in range(m):
                for c in range(n):
                    if dp[r][c] == 0:
                        continue

                    # For each possible direction
                    for dr, dc in directions:
                        nr, nc = r + dr, c + dc

                        # Check if the new position is outside the grid
                        if not (0 <= nr < m and 0 <= nc < n):
                            total_paths = (total_paths + dp[r][c]) % MOD
                        else:
                            next_dp[nr][nc] = (next_dp[nr][nc] + dp[r][c]) % MOD

            # Update dp for the next iteration (next move)
            dp = next_dp

        return total_paths

class Solution:
    def strobogrammaticInRange(self, low: str, high: str) -> int:

        # Valid strobogrammatic digit pairs
        pairs = [('0', '0'), ('1', '1'), ('6', '9'), ('8', '8'), ('9', '6')]

        # Helper to generate all strobogrammatic numbers of exact length 'n'
        def generate(n, current_len):
            if current_len == 0:
                return [""]
            if current_len == 1:
                return ["0", "1", "8"]

            res = []
            prev = generate(n, current_len - 2)
            for s in prev:
                for p_left, p_right in pairs:
                    # Do not place '0' at the start if current_len is the original n
                    if p_left == '0' and current_len == n:
                        continue
                    res.append(p_left + s + p_right)
            return res

        count = 0
        len_low, len_high = len(low), len(high)

        # Compare strings numerically:
        # A number is valid if:
        # 1. len(s) > len(low) and len(s) < len(high)
        # 2. len(s) == len(low) and int(s) >= int(low)
        # 3. len(s) == len(high) and int(s) <= int(high)

        for length in range(len_low, len_high + 1):
            candidates = generate(length, length)
            for s in candidates:
                if length == len_low and length == len_high:
                    if int(low) <= int(s) <= int(high):
                        count += 1
                elif length == len_low:
                    if int(s) >= int(low):
                        count += 1
                elif length == len_high:
                    if int(s) <= int(high):
                        count += 1
                else:
                    count += 1
        return count

