    def strobogrammaticInRange(self, low: str, high: str) -> int:

        # Define the valid strobogrammatic digit pairs
        pairs = [('0', '0'), ('1', '1'), ('6', '9'), ('8', '8'), ('9', '6')]

        # Helper function to generate all strobogrammatic numbers of length n
        def generate(n, current_n):
            if current_n == 0:
                return [""]
            if current_n == 1:
                return ["0", "1", "8"]

            prev_strobos = generate(n, current_n - 2)
            current_strobos = []
            for s in prev_strobos:
                for p_left, p_right in pairs:
                    # Prevent leading zero if the number has more than 1 digit
                    if n > 1 and p_left == '0' and current_n == n:
                        continue
                    current_strobos.append(p_left + s + p_right)
            return current_strobos

        count = 0
        low_len, high_len = len(low), len(high)

        # Iterate through possible lengths
        for length in range(low_len, high_len + 1):
            strobos = generate(length, length)

            for s_num_str in strobos:
                # Numerical comparison logic
                # If length is equal to low length, must be >= low
                # If length is equal to high length, must be <= high
                # If length is in between, it is automatically valid

                if length == low_len and length == high_len:
                    if int(low) <= int(s_num_str) <= int(high):
                        count += 1
                elif length == low_len:
                    if int(s_num_str) >= int(low):
                        count += 1
                elif length == high_len:
                    if int(s_num_str) <= int(high):
                        count += 1
                else:
                    count += 1

        return count

