                # Compare lengths first, then strings lexicographically
                # We know all strings in 'strobos' have the same length
                if len(s) == len(low) and len(s) == len(high):
                    if low <= s <= high:
                        count += 1
                elif len(s) == len(low):
                    if s >= low:
                        count += 1
                elif len(s) == len(high):
                    if s <= high:
                        count += 1
                else:
                    # Intermediate lengths are always within [low, high]
                    count += 1

        return count

