from typing import List

class Solution:
    def makeConnected(self, n: int, connections: List[List[int]]) -> int:
        # Condition 1: To connect n computers, we need at least n-1 cables.
        if len(connections) < n - 1:
            return -1

        # DSU (Disjoint Set Union) structure to find connected components
        parent = list(range(n))

        def find(i):
            if parent[i] == i:
                return i
            parent[i] = find(parent[i]) # Path compression
            return parent[i]

        def union(i, j):
            root_i = find(i)
            root_j = find(j)
            if root_i != root_j:
                parent[root_i] = root_j
                return True # Merged two distinct components
            return False # Already in the same component

        # Process all connections to build the current network components
        for u, v in connections:
            union(u, v)

        # Count the number of connected components
        num_components = 0
        for i in range(n):
            if parent[i] == i:
                num_components += 1

        # To connect 'num_components' components into one, we need 'num_components - 1' cables.
        # Since we have checked len(connections) >= n - 1, it is guaranteed that we have 
        # enough excess cables to connect the components.
        return num_components - 1

import math

class Solution:
    def tilingRectangle(self, n: int, m: int) -> int:
        # Swap n and m if n > m to ensure n <= m, reducing state space for memoization.
        if n > m:
            n, m = m, n

        # Memoization table to store results for subproblems
        memo = {}

        # `find_uncovered(current_covered_state)`:
        # Finds the first (top-most, left-most) uncovered cell (r, c).
        # Returns (r, c) or (-1, -1) if all covered.
        def find_uncovered(current_covered_state):
            for r in range(n):
                # Optimization: skip if row is full
                if current_covered_state[r] == (1 << m) - 1:
                    continue
                for c in range(m):
                    if not (current_covered_state[r] & (1 << c)):
                        return r, c
            return -1, -1

        # `solve(current_covered_state)`:
        def solve(current_covered_state_tuple):
            if current_covered_state_tuple in memo:
                return memo[current_covered_state_tuple]

            r, c = find_uncovered(current_covered_state_tuple)

            if r == -1:
                return 0

            min_count = float('inf')

            # Determine maximum possible square size
            max_s = 0
            for i in range(r, n):
                if not (current_covered_state_tuple[i] & (1 << c)):
                    max_s += 1
                else:
                    break
            max_s = min(max_s, m - c)

            # Try placing a square of size `s` at (r, c)
            for s in range(max_s, 0, -1):
                # Check if square fits (must be clear of other squares)
                can_place = True
                for i in range(r, r + s):
                    for j in range(c, c + s):
                        if (current_covered_state_tuple[i] & (1 << j)):
                            can_place = False
                            break
                    if not can_place: break

                if can_place:
                    next_covered_state = list(current_covered_state_tuple)
                    for i in range(r, r + s):
                        for j in range(c, c + s):
                            next_covered_state[i] |= (1 << j)

                    res = 1 + solve(tuple(next_covered_state))
                    min_count = min(min_count, res)

            memo[current_covered_state_tuple] = min_count
            return min_count

        # Special case: 11x13 is a known edge case where greedy/standard DFS 
        # might be slow, but memoization and correct pruning handle it.
        return solve(tuple([0] * n))

class Solution:
    def maximumTime(self, time: str) -> str:
        time_list = list(time)

        # Handle hours
        # First digit of hour (H1)
        if time_list[0] == '?':
            # If H2 is '?' or '0'/'1'/'2'/'3', H1 can be '2'
            # If H2 is '4' through '9', H1 must be '1'
            if time_list[1] == '?' or int(time_list[1]) <= 3:
                time_list[0] = '2'
            else:
                time_list[0] = '1'

        # Second digit of hour (H2)
        if time_list[1] == '?':
            if time_list[0] == '2':
                # If H1 is '2', H2 can be at most '3' (for 23:xx)
                time_list[1] = '3'
            else: 
                # If H1 is '0' or '1', H2 can be at most '9'
                time_list[1] = '9'

        # Handle minutes
        # First digit of minute (M1)
        if time_list[3] == '?':
            # M1 can be at most '5' (for xx:5x)
            time_list[3] = '5'

        # Second digit of minute (M2)
        if time_list[4] == '?':
            # M2 can be at most '9' (for xx:x9)
            time_list[4] = '9'

        return "".join(time_list)

