from collections import deque
from typing import List

class Solution:
    def minFlips(self, mat: List[List[int]]) -> int:
        m = len(mat)
        n = len(mat[0])

        # Helper function to convert a matrix to an integer
        def get_int_from_mat(current_mat: List[List[int]]) -> int:
            val = 0
            for r in range(m):
                for c in range(n):
                    val = (val << 1) | current_mat[r][c]
            return val

        # Helper function to convert an integer back to a matrix
        def get_mat_from_int(state_int: int) -> List[List[int]]:
            temp_mat = [[0] * n for _ in range(m)]
            for r in range(m - 1, -1, -1):
                for c in range(n - 1, -1, -1):
                    temp_mat[r][c] = state_int & 1
                    state_int >>= 1
            return temp_mat

        # Helper function to perform a flip operation at (r, c)
        def flip(current_mat: List[List[int]], r: int, c: int):
            neighbors = [(0, 0), (0, 1), (0, -1), (1, 0), (-1, 0)]
            for dr, dc in neighbors:
                nr, nc = r + dr, c + dc
                if 0 <= nr < m and 0 <= nc < n:
                    current_mat[nr][nc] ^= 1

        # BFS Initialization
        initial_state_int = get_int_from_mat(mat)

        # Queue stores (state_as_int, steps)
        q = deque([(initial_state_int, 0)])

        # Set to keep track of visited states
        visited = {initial_state_int}

        # BFS Loop
        while q:
            current_state_int, steps = q.popleft()

            # If current state is the zero matrix, we found the shortest path
            if current_state_int == 0:
                return steps

            current_mat = get_mat_from_int(current_state_int)

            # Try flipping each cell (r, c)
            for r in range(m):
                for c in range(n):
                    next_mat = [row[:] for row in current_mat]
                    flip(next_mat, r, c)
                    next_state_int = get_int_from_mat(next_mat)

                    if next_state_int not in visited:
                        visited.add(next_state_int)
                        q.append((next_state_int, steps + 1))

        return -1

class Solution:
    def canConvert(self, str1: str, str2: str) -> bool:
        # If str1 and str2 are already identical, no conversions are needed.
        if str1 == str2:
            return True

        # If str1 and str2 have different lengths, it's impossible to map 1:1.
        # Although the problem says they have the same length, this is a safety check.
        if len(str1) != len(str2):
            return False

        # We need to establish a mapping from characters in str1 to characters in str2.
        # This mapping must be consistent: if str1[i] maps to str2[i], then
        # all other occurrences of str1[i] must also map to str2[i].
        mapping = {}

        for i in range(len(str1)):
            char1 = str1[i]
            char2 = str2[i]

            if char1 in mapping:
                if mapping[char1] != char2:
                    return False
            else:
                mapping[char1] = char2

        # After checking for consistent mapping (a function from str1 to str2),
        # we check the constraint on target availability. 
        # If all 26 lowercase English letters are used in str2 as targets, 
        # we cannot resolve circular dependencies (e.g., 'a' -> 'b', 'b' -> 'a').
        # If len(set(str2)) < 26, we can always find an intermediate character.
        return len(set(str2)) < 26

class Solution:
    def buildArray(self, nums: List[int]) -> List[int]:
        n = len(nums)
        # To achieve O(1) extra space (excluding the return array),
        # we encode two numbers in one slot using the formula:
        # new_val = old_val + (new_target % n) * n
        # This works because all nums[i] are < n.

        for i in range(n):
            nums[i] += (nums[nums[i]] % n) * n

        for i in range(n):
            nums[i] //= n

        return nums

