        # Precompute counts for rows
        # onesRow[i] stores the number of ones in row i
        # zerosRow[i] stores the number of zeros in row i
        onesRow = [0] * m
        zerosRow = [0] * m
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 1:
                    onesRow[i] += 1
                else:
                    zerosRow[i] += 1

        # Precompute counts for columns
        # onesCol[j] stores the number of ones in column j
        # zerosCol[j] stores the number of zeros in column j
        onesCol = [0] * n
        zerosCol = [0] * n
        for j in range(n):
            for i in range(m):
                if grid[i][j] == 1:
                    onesCol[j] += 1
                else:
                    zerosCol[j] += 1

        # Calculate the difference matrix
        diff = [[0] * n for _ in range(m)]
        for i in range(m):
            for j in range(n):
                diff[i][j] = onesRow[i] + onesCol[j] - zerosRow[i] - zerosCol[j]

        return diff

import collections
from typing import List

class Solution:
    def reconstructMatrix(self, upper: int, lower: int, colsum: List[int]) -> List[List[int]]:
        n = len(colsum)

        # Initialize the result matrix with zeros
        matrix = [[0] * n for _ in range(2)]

        # First pass: Handle columns with colsum[i] == 2
        # These columns must have 1s in both rows.
        for i in range(n):
            if colsum[i] == 2:
                matrix[0][i] = 1
                matrix[1][i] = 1
                upper -= 1
                lower -= 1

        # Check if row sums have become negative after handling '2's.
        # This implies an invalid state immediately.
        if upper < 0 or lower < 0:
            return []

        # Second pass: Handle columns with colsum[i] == 1
        # For these columns, we strategically place the '1' to satisfy 'upper' first, then 'lower'.
        for i in range(n):
            if colsum[i] == 1:
                if upper > 0:
                    matrix[0][i] = 1
                    upper -= 1
                elif lower > 0:
                    matrix[1][i] = 1
                    lower -= 1
                else:
                    # If both upper and lower are 0, but we still have a colsum[i] == 1,
                    # it means we cannot place this '1' and no solution exists.
                    return []

        # After processing all columns, both upper and lower should be 0.
        # If not, it means we couldn't distribute the '1's correctly.
        if upper == 0 and lower == 0:
            return matrix
        else:
            return []

