class Solution:
    def largestMerge(self, word1: str, word2: str) -> str:
        merge = []
        p1 = 0
        p2 = 0
        n1 = len(word1)
        n2 = len(word2)

        while p1 < n1 or p2 < n2:
            # The simple comparison word1[p1:] > word2[p2:] is correct 
            # and handles the lexicographical requirement directly in Python.
            if word1[p1:] > word2[p2:]:
                merge.append(word1[p1])
                p1 += 1
            else:
                merge.append(word2[p2])
                p2 += 1

        return "".join(merge)

import collections
from typing import List

class Solution:
    def maximumCost(self, n: int, highways: List[List[int]], k: int) -> int:
        # If k is larger than n-1, it's impossible to traverse k highways without repeating a city.
        if k >= n:
            return -1

        # Build adjacency list
        adj = collections.defaultdict(list)
        for u, v, toll in highways:
            adj[u].append((v, toll))
            adj[v].append((u, toll))

        # dp[mask][last_city] stores the maximum cost to reach last_city 
        # with visited cities represented by mask.
        # Since we need exactly k edges, the number of set bits in the mask 
        # must be equal to (number of edges + 1).
        dp = [{} for _ in range(1 << n)]

        # Base cases: Starting at any city i with 0 edges, cost 0, mask 1 << i.
        for i in range(n):
            dp[1 << i][i] = 0

        # Iterate through the number of edges already traversed.
        # We need to reach exactly k edges.
        for _ in range(k):
            next_dp = [{} for _ in range(1 << n)]
            for mask in range(1 << n):
                for u, current_cost in dp[mask].items():
                    # Try to extend to an unvisited neighbor v
                    for v, toll in adj[u]:
                        if not (mask & (1 << v)):
                            new_mask = mask | (1 << v)
                            new_cost = current_cost + toll
                            if new_cost > next_dp[new_mask].get(v, -1):
                                next_dp[new_mask][v] = new_cost
            dp = next_dp

        max_total_cost = -1
        # Check all masks that have exactly k+1 cities (k edges)
        for mask in range(1 << n):
            if bin(mask).count('1') == k + 1:
                for last_city in dp[mask]:
                    max_total_cost = max(max_total_cost, dp[mask][last_city])

        return max_total_cost

