import collections
from typing import List

class Solution:
    def maximumCost(self, n: int, highways: List[List[int]], k: int) -> int:
        # Since n is small (up to 15), we can use dynamic programming with bitmasking.
        # Since k can be up to 50, but we can only visit each city at most once,
        # if k >= n, we cannot visit k edges (max edges is n-1).
        if k >= n:
            return -1

        # Initialize an adjacency list for the graph.
        adj = collections.defaultdict(list)
        for u, v, toll in highways:
            adj[u].append((v, toll))
            adj[v].append((u, toll))

        # dp table: (mask, last_city) -> max_cost for current path length.
        # We process the number of edges incrementally.
        # dp[mask][last_city] = max_cost for a path of current_len.
        dp = {}

        # Base cases: Starting a trip from any city (0 edges).
        for i in range(n):
            dp[(1 << i, i)] = 0

        # Iterate through path lengths from 0 to k-1.
        for _ in range(k):
            new_dp = {}
            for (mask, u), current_cost in dp.items():
                # Try to extend the trip from city 'u' to an unvisited neighbor 'v'.
                for v, toll in adj[u]:
                    # Check if 'v' has not been visited yet.
                    if not (mask & (1 << v)):
                        new_mask = mask | (1 << v)
                        new_cost = current_cost + toll

                        state = (new_mask, v)
                        if new_cost > new_dp.get(state, -1):
                            new_dp[state] = new_cost
            dp = new_dp

        # After filling the DP table for k edges, find the maximum cost.
        if not dp:
            return -1

        return max(dp.values())

