import collections
from typing import List

class Solution:
    def maximumCost(self, n: int, highways: List[List[int]], k: int) -> int:
        # Since the problem requires a path of exactly k highways (which implies k+1 cities),
        # if k >= n, it is impossible to have a simple path (no repeated cities).
        if k >= n:
            return -1

        # Initialize an adjacency list for the graph.
        adj = collections.defaultdict(list)
        for u, v, toll in highways:
            adj[u].append((v, toll))
            adj[v].append((u, toll))

        # dp[(mask, last_city)] will store the maximum cost to reach 'last_city'
        # having visited cities in 'mask', where the number of edges is implicitly 
        # the number of set bits in mask minus 1.
        dp = {}

        # Base cases: Starting a trip from any city.
        # path_len = 0 (0 edges) at city i.
        for i in range(n):
            dp[(1 << i, i)] = 0

        # We need to perform k steps (adding k edges).
        for _ in range(k):
            new_dp = {}
            for (mask, u), current_cost in dp.items():
                for v, toll in adj[u]:
                    # Ensure v has not been visited yet.
                    if not (mask & (1 << v)):
                        new_mask = mask | (1 << v)
                        new_cost = current_cost + toll
                        # Keep track of the maximum cost for this state.
                        if new_cost > new_dp.get((new_mask, v), -1):
                            new_dp[(new_mask, v)] = new_cost
            dp = new_dp

        # The answer is the maximum cost among all states in the dp dictionary.
        # If no states exist after k steps, return -1.
        if not dp:
            return -1

        return max(dp.values())

