import collections
from typing import List

class Solution:
    def maximumCost(self, n: int, highways: List[List[int]], k: int) -> int:
        # Since n is small (up to 10-15 typical for this type of constraint), 
        # we can use DFS with memoization or DP with bitmasking.

        adj = collections.defaultdict(list)
        for u, v, toll in highways:
            adj[u].append((v, toll))
            adj[v].append((u, toll))

        # Memoization dictionary: (mask, last_city, edges_remaining)
        memo = {}

        def dfs(mask, u, edges_left):
            if edges_left == 0:
                return 0

            state = (mask, u, edges_left)
            if state in memo:
                return memo[state]

            max_c = -float('inf')

            for v, toll in adj[u]:
                if not (mask & (1 << v)):
                    res = dfs(mask | (1 << v), v, edges_left - 1)
                    if res != -float('inf'):
                        max_c = max(max_c, toll + res)

            memo[state] = max_c
            return max_c

        ans = -1
        for i in range(n):
            res = dfs(1 << i, i, k)
            if res != -float('inf'):
                ans = max(ans, res)

        return ans

