import collections
from typing import List

class Solution:
    def maximumCost(self, n: int, highways: List[List[int]], k: int) -> int:
        # If k >= n, we cannot visit k highways without visiting at least one city twice,
        # because a simple path of length k uses k+1 cities.
        if k >= n:
            return -1

        # Initialize an adjacency list for the graph.
        adj = collections.defaultdict(list)
        for u, v, toll in highways:
            adj[u].append((v, toll))
            adj[v].append((u, toll))

        # dp[mask][last_city] stores the maximum cost to reach 'last_city'
        # having visited the set of cities represented by 'mask'.
        # We process step-by-step for the path length.
        # dp[path_len][mask][last_city]
        dp = [{} for _ in range(k + 1)]

        # Base cases: Starting at any city with 0 edges
        for i in range(n):
            dp[0][(1 << i, i)] = 0

        # Build up to k edges
        for length in range(k):
            for (mask, u), current_cost in dp[length].items():
                for v, toll in adj[u]:
                    if not (mask & (1 << v)):
                        new_mask = mask | (1 << v)
                        new_cost = current_cost + toll

                        state = (new_mask, v)
                        if new_cost > dp[length + 1].get(state, -1):
                            dp[length + 1][state] = new_cost

        # Find the maximum cost among all states that have exactly 'k' edges
        if not dp[k]:
            return -1

        return max(dp[k].values())

