import heapq
from typing import List

class Solution:
    def kClosest(self, points: List[List[int]], k: int) -> List[List[int]]:
        # Using nsmallest to get the k smallest elements based on the squared distance.
        # This is more efficient (O(N + K log N) or O(N log K)) than pushing all to a heap 
        # and popping k times (O(N log N)).
        return heapq.nsmallest(k, points, key=lambda p: p[0]**2 + p[1]**2)

class Solution:
    def minMaxDifference(self, num: int) -> int:
        s_num = str(num)

        # --- Calculate Max Value ---
        # To get the maximum value, we replace the first non-'9' digit with '9'.
        max_val_str = list(s_num)
        digit_to_change_for_max = ''

        for digit in s_num:
            if digit != '9':
                digit_to_change_for_max = digit
                break

        if digit_to_change_for_max:
            for i in range(len(max_val_str)):
                if max_val_str[i] == digit_to_change_for_max:
                    max_val_str[i] = '9'
        max_val = int("".join(max_val_str))

        # --- Calculate Min Value ---
        # To get the minimum value, we replace the first digit (which is non-zero,
        # unless num is 0, but the problem constraints imply positive integers)
        # with '0'.
        min_val_str = list(s_num)
        digit_to_change_for_min = s_num[0]

        for i in range(len(min_val_str)):
            if min_val_str[i] == digit_to_change_for_min:
                min_val_str[i] = '0'
        min_val = int("".join(min_val_str))

        return max_val - min_val

