from typing import List

class Solution:
    def maximumScore(self, grid: List[List[int]]) -> int:
        n = len(grid)
        # Precompute prefix sums for each column to calculate sums in O(1)
        # col_pref[j][i] = sum(grid[0...i-1][j])
        col_pref = [[0] * (n + 1) for _ in range(n)]
        for j in range(n):
            for i in range(n):
                col_pref[j][i + 1] = col_pref[j][i] + grid[i][j]

        # dp[i] is the max score ending at the previous column with i black cells.
        # Initialize with j=0 (first column). No previous columns, so score is 0.
        dp = [0] * (n + 1)

        for j in range(1, n):
            new_dp = [-1] * (n + 1)
            # Precompute gain[i_prev][i_curr]
            # When moving from column j-1 (i_prev black) to column j (i_curr black):
            # 1. White in j-1, Black in j: rows r where i_prev <= r < i_curr. Sum grid[r][j-1]
            # 2. Black in j-1, White in j: rows r where i_curr <= r < i_prev. Sum grid[r][j]

            for i_curr in range(n + 1):
                for i_prev in range(n + 1):
                    gain = 0
                    if i_curr > i_prev:
                        # sum of grid[r][j-1] for r in [i_prev, i_curr-1]
                        gain = col_pref[j-1][i_curr] - col_pref[j-1][i_prev]
                    elif i_prev > i_curr:
                        # sum of grid[r][j] for r in [i_curr, i_prev-1]
                        gain = col_pref[j][i_prev] - col_pref[j][i_curr]

                    if dp[i_prev] != -1:
                        new_dp[i_curr] = max(new_dp[i_curr], dp[i_prev] + gain)
            dp = new_dp

        return max(dp)

from typing import List

class Solution:
    def minArea(self, image: List[List[str]], x: int, y: int) -> int:
        m = len(image)
        if m == 0:
            return 0
        n = len(image[0])
        if n == 0:
            return 0

        def has_black_in_row(r: int) -> bool:
            return '1' in image[r]

        def has_black_in_col(c: int) -> bool:
            for r in range(m):
                if image[r][c] == '1':
                    return True
            return False

        # Binary search for row boundaries
        min_r, max_r = x, x
        low, high = 0, x
        while low <= high:
            mid = (low + high) // 2
            if has_black_in_row(mid):
                min_r = mid
                high = mid - 1
            else:
                low = mid + 1

        low, high = x, m - 1
        while low <= high:
            mid = (low + high) // 2
            if has_black_in_row(mid):
                max_r = mid
                low = mid + 1
            else:
                high = mid - 1

        # Binary search for column boundaries
        min_c, max_c = y, y
        low, high = 0, y
        while low <= high:
            mid = (low + high) // 2
            if has_black_in_col(mid):
                min_c = mid
                high = mid - 1
            else:
                low = mid + 1

        low, high = y, n - 1
        while low <= high:
            mid = (low + high) // 2
            if has_black_in_col(mid):
                max_c = mid
                low = mid + 1
            else:
                high = mid - 1

        return (max_r - min_r + 1) * (max_c - min_c + 1)

