        low, high = y, n - 1
        max_c = y
        while low <= high:
            mid = (low + high) // 2
            if has_black_col(mid):
                max_c = mid
                low = mid + 1
            else:
                high = mid - 1

        return (max_r - min_r + 1) * (max_c - min_c + 1)

