class Solution:
    def countMatchingSubarrays(self, nums: List[int], pattern: List[int]) -> int:
        n = len(nums)
        m = len(pattern)

        # Transform the nums array into a sequence of relationships
        # S[i] = 1 if nums[i+1] > nums[i], 0 if equal, -1 if less
        s = []
        for i in range(n - 1):
            if nums[i + 1] > nums[i]:
                s.append(1)
            elif nums[i + 1] == nums[i]:
                s.append(0)
            else:
                s.append(-1)

        # Now find the occurrences of pattern in s using KMP algorithm
        # Create the LPS (Longest Prefix Suffix) array for the pattern
        lps = [0] * m
        j = 0
        for i in range(1, m):
            while j > 0 and pattern[i] != pattern[j]:
                j = lps[j - 1]
            if pattern[i] == pattern[j]:
                j += 1
            lps[i] = j

        # Search for pattern in s
        count = 0
        j = 0
        for i in range(len(s)):
            while j > 0 and s[i] != pattern[j]:
                j = lps[j - 1]
            if s[i] == pattern[j]:
                j += 1
            if j == m:
                count += 1
                j = lps[j - 1]

        return count

