class Solution:
    def isMatch(self, s: str, p: str) -> bool:
        m = len(s)
        n = len(p)

        # dp[i][j] will be True if the first i characters of s match the first j characters of p
        dp = [[False] * (n + 1) for _ in range(m + 1)]

        # Base case: empty string matches empty pattern
        dp[0][0] = True

        # Fill the first row: s is empty, p is not empty
        # Only '*' can match an empty string
        for j in range(1, n + 1):
            if p[j - 1] == '*':
                dp[0][j] = dp[0][j - 1] 

        # Fill the DP table
        for i in range(1, m + 1):
            for j in range(1, n + 1):
                s_char = s[i - 1]
                p_char = p[j - 1]

                if p_char == s_char or p_char == '?':
                    # If characters match or p_char is '?',
                    # then match depends on the previous subproblem
                    dp[i][j] = dp[i - 1][j - 1]
                elif p_char == '*':
                    # '*' can match an empty sequence (dp[i][j-1])
                    # OR '*' can match the current character in s (dp[i-1][j])
                    dp[i][j] = dp[i][j - 1] or dp[i - 1][j]
                else:
                    # Characters don't match and p_char is not '?' or '*'
                    dp[i][j] = False

        return dp[m][n]

class Solution:
    def calculate(self, s: str) -> int:
        if not s:
            return 0

        stack = []
        current_number = 0
        current_operator = '+'
        n = len(s)

        for i in range(n):
            char = s[i]

            if char.isdigit():
                current_number = current_number * 10 + int(char)

            # If char is an operator or we reached the end of the string
            if (not char.isdigit() and char != ' ') or i == n - 1:
                if current_operator == '+':
                    stack.append(current_number)
                elif current_operator == '-':
                    stack.append(-current_number)
                elif current_operator == '*':
                    stack.append(stack.pop() * current_number)
                elif current_operator == '/':
                    # Use int(a / b) to ensure truncation towards zero
                    operand = stack.pop()
                    stack.append(int(operand / current_number))

                # Update the operator and reset the current number
                current_operator = char
                current_number = 0

        return sum(stack)

