class Solution:
    def isIsomorphic(self, s: str, t: str) -> bool:
        # We need two maps to ensure a one-to-one mapping:
        # 1. s_to_t: maps characters from s to characters from t
        # 2. t_to_s: maps characters from t to characters from s (to check reverse consistency)
        s_to_t = {}
        t_to_s = {}

        # Iterate through the strings simultaneously
        for char_s, char_t in zip(s, t):
            # Case 1: char_s has been seen before in s_to_t
            if char_s in s_to_t:
                # If char_s maps to something, it must map to char_t
                # for the current position. If not, they are not isomorphic.
                if s_to_t[char_s] != char_t:
                    return False
            # Case 2: char_s has not been seen before in s_to_t
            else:
                # Before adding a new mapping for char_s,
                # we must ensure that char_t has not already been mapped
                # from a *different* character in s.
                if char_t in t_to_s:
                    return False # char_t is already mapped from a different char_s

                # If both checks pass, establish the new mappings
                s_to_t[char_s] = char_t
                t_to_s[char_t] = char_s # Store reverse mapping for consistency check

        # If the loop completes, it means all characters were consistently mapped
        return True

