from collections import defaultdict
from typing import List

class Solution:
    def smallestMissingValueSubtree(self, parents: List[int], nums: List[int]) -> List[int]:
        n = len(parents)
        adj = [[] for _ in range(n)]
        for i, p in enumerate(parents):
            if p != -1:
                adj[p].append(i)

        ans = [1] * n

        # Identify the node containing value 1
        node_with_one = -1
        for i, val in enumerate(nums):
            if val == 1:
                node_with_one = i
                break

        # If 1 is not present, all subtrees have 1 as the smallest missing value
        if node_with_one == -1:
            return ans

        # seen_values tracks all genetic values in the subtree currently being traversed
        seen_values = set()

        def get_all_values(u):
            seen_values.add(nums[u])
            for v in adj[u]:
                if nums[v] not in seen_values:
                    get_all_values(v)

        curr_missing = 1
        curr_node = node_with_one

        # Only nodes on the path from node_with_one to the root can have missing values > 1
        # because those are the only nodes that contain value 1 in their subtree.
        while curr_node != -1:
            # Perform DFS to collect all genetic values in the current subtree
            # We skip nodes that were already visited in previous subtrees on this path
            get_all_values(curr_node)

            # Increment missing value until we find one not in the current subtree
            while curr_missing in seen_values:
                curr_missing += 1

            ans[curr_node] = curr_missing
            curr_node = parents[curr_node]

        return ans

class Solution:
    def longestDupSubstring(self, s: str) -> str:
        n = len(s)

        # Using a larger modulus or double hashing reduces the probability of collisions.
        # 2**63 - 1 is a large Mersenne prime.
        mod = (1 << 63) - 1
        base = 26

        pow_base = [1] * (n + 1)
        for i in range(1, n + 1):
            pow_base[i] = (pow_base[i-1] * base) % mod

        def check(L: int) -> str:
            if L == 0:
                return ""

            current_hash = 0
            for i in range(L):
                current_hash = (current_hash * base + (ord(s[i]) - ord('a'))) % mod

            seen_hashes = {current_hash: [0]} 

            for i in range(1, n - L + 1):
                # Update hash: subtract leading, add trailing
                current_hash = (current_hash - (ord(s[i-1]) - ord('a')) * pow_base[L-1]) % mod
                current_hash = (current_hash * base + (ord(s[i+L-1]) - ord('a'))) % mod

                if current_hash in seen_hashes:
                    # Double check to handle potential collisions
                    sub = s[i : i + L]
                    for start_idx in seen_hashes[current_hash]:
                        if s[start_idx : start_idx + L] == sub:
                            return sub
                    seen_hashes[current_hash].append(i)
                else:
                    seen_hashes[current_hash] = [i]

            return ""

        # Binary search for the maximum length L
        low = 1
        high = n - 1
        res = ""

        while low <= high:
            mid = (low + high) // 2
            candidate = check(mid)
            if candidate:
                res = candidate
                low = mid + 1
            else:
                high = mid - 1

        return res

