import collections
from typing import List

class Solution:
    def canMouseWin(self, grid: List[str], catJump: int, mouseJump: int) -> bool:
        rows, cols = len(grid), len(grid[0])
        mouse_start = cat_start = food_pos = None

        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == 'M': mouse_start = (r, c)
                elif grid[r][c] == 'C': cat_start = (r, c)
                elif grid[r][c] == 'F': food_pos = (r, c)

        dr, dc = [-1, 1, 0, 0], [0, 0, -1, 1]
        MAX_TURNS = 70  # Sufficiently large state space for 8x8 grid

        # State: (m_r, m_c, c_r, c_c, turn, player)
        # player: 0 = Mouse, 1 = Cat
        # dp: 1 = Mouse win, 2 = Cat win
        dp = {}
        degree = {}

        def get_degree(m_r, m_c, c_r, c_c, turn, player):
            count = 0
            if player == 0:
                # Mouse move options
                for i in range(4):
                    for jump in range(mouseJump + 1):
                        nr, nc = m_r + dr[i] * jump, m_c + dc[i] * jump
                        if not (0 <= nr < rows and 0 <= nc < cols) or grid[nr][nc] == '#':
                            if jump > 0: break
                            continue
                        count += 1
            else:
                # Cat move options
                for i in range(4):
                    for jump in range(catJump + 1):
                        nr, nc = c_r + dr[i] * jump, c_c + dc[i] * jump
                        if not (0 <= nr < rows and 0 <= nc < cols) or grid[nr][nc] == '#':
                            if jump > 0: break
                            continue
                        count += 1
            return count

        q = collections.deque()

        # Terminal conditions
        for t in range(MAX_TURNS + 1):
            for m_r in range(rows):
                for m_c in range(cols):
                    if grid[m_r][m_c] == '#': continue
                    for c_r in range(rows):
                        for c_c in range(cols):
                            if grid[c_r][c_c] == '#': continue

                            # Cat wins if turn limit reached
                            if t == MAX_TURNS:
                                for p in [0, 1]:
                                    if (m_r, m_c, c_r, c_c, t, p) not in dp:
                                        dp[(m_r, m_c, c_r, c_c, t, p)] = 2
                                        q.append((m_r, m_c, c_r, c_c, t, p))

                            # Cat wins if same pos
                            if (m_r, m_c) == (c_r, c_c):
                                for p in [0, 1]:
                                    if (m_r, m_c, c_r, c_c, t, p) not in dp:
                                        dp[(m_r, m_c, c_r, c_c, t, p)] = 2
                                        q.append((m_r, m_c, c_r, c_c, t, p))

                            # Mouse wins if mouse at food
                            if (m_r, m_c) == food_pos:
                                for p in [0, 1]:
                                    if (m_r, m_c, c_r, c_c, t, p) not in dp:
                                        dp[(m_r, m_c, c_r, c_c, t, p)] = 1
                                        q.append((m_r, m_c, c_r, c_c, t, p))

                            # Cat wins if cat at food
                            if (c_r, c_c) == food_pos:
                                for p in [0, 1]:
                                    if (m_r, m_c, c_r, c_c, t, p) not in dp:
                                        dp[(m_r, m_c, c_r, c_c, t, p)] = 2
                                        q.append((m_r, m_c, c_r, c_c, t, p))

        while q:
            m_r, m_c, c_r, c_c, t, p = q.popleft()
            res = dp[(m_r, m_c, c_r, c_c, t, p)]

            if t == 0: continue

            # Prev state
            pt = t - 1
            if p == 1: # Previous was Mouse turn
                for i in range(4):
                    for jump in range(mouseJump + 1):
                        pr, pc = m_r - dr[i] * jump, m_c - dc[i] * jump
                        if not (0 <= pr < rows and 0 <= pc < cols) or grid[pr][pc] == '#':
                            if jump > 0: break
                            continue
                        state = (pr, pc, c_r, c_c, pt, 0)
                        if state not in dp:
                            if res == 1: dp[state] = 1; q.append(state)
                            else:
                                degree[state] = degree.get(state, get_degree(*state)) - 1
                                if degree[state] == 0: dp[state] = 2; q.append(state)
            else: # Previous was Cat turn
                for i in range(4):
                    for jump in range(catJump + 1):
                        pr, pc = c_r - dr[i] * jump, c_c - dc[i] * jump
                        if not (0 <= pr < rows and 0 <= pc < cols) or grid[pr][pc] == '#':
                            if jump > 0: break
                            continue
                        state = (m_r, m_c, pr, pc, pt, 1)
                        if state not in dp:
                            if res == 2: dp[state] = 2; q.append(state)
                            else:
                                degree[state] = degree.get(state, get_degree(*state)) - 1
                                if degree[state] == 0: dp[state] = 1; q.append(state)

        return dp.get((mouse_start[0], mouse_start[1], cat_start[0], cat_start[1], 0, 0)) == 1

