import collections
from typing import List

class Solution:
    def canMouseWin(self, grid: List[str], catJump: int, mouseJump: int) -> bool:
        rows, cols = len(grid), len(grid[0])

        # Find initial positions of Cat, Mouse, and Food
        mouse_start = (-1, -1)
        cat_start = (-1, -1)
        food_pos = (-1, -1)

        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == 'M':
                    mouse_start = (r, c)
                elif grid[r][c] == 'C':
                    cat_start = (r, c)
                elif grid[r][c] == 'F':
                    food_pos = (r, c)

        # Directions for movement
        dr = [-1, 1, 0, 0]
        dc = [0, 0, -1, 1]

        # Max turns for the game to end in a draw (Cat wins)
        # A state is (mouse_pos, cat_pos, turn_idx, player_to_move).
        # (rows*cols)^2 * 2 states.
        # Max turns is 1000. Each turn is one player's move.
        # So, turn_idx goes from 0 to 999.
        # If turn_idx reaches 1000, it's a draw (Cat wins).
        # The problem states "within 1000 turns", implying 1000 turns have passed.
        # So, turn_idx can go up to 999 for a player to move.
        # If it's turn 1000 (turn_idx=1000), the game is over.
        MAX_TURNS = 1000

        # DP state: (mouse_r, mouse_c, cat_r, cat_c, turn_idx, player_to_move)
        # player_to_move: 0 for Mouse, 1 for Cat
        # Values:
        # 0: Unknown (default)
        # 1: Mouse wins
        # 2: Cat wins
        dp = collections.defaultdict(int) # Default value 0 (Unknown)

        # Degrees for each state (m_r, m_c, c_r, c_c, turn_idx, player_to_move)
        # This will store how many moves from this state lead to an unknown outcome.
        # For a player to win, they need at least one move to an opponent's losing state.
        # For a player to lose, all their moves must lead to opponent's winning states.
        # We count the number of moves that *don't* immediately lead to a win for the current player.
        # If this count drops to 0, and no winning move was found, then the current player loses.

        # We'll use a queue for a BFS-like approach (backward DP)
        # The queue will store states whose outcome has been determined.
        q = collections.deque()

        # Initialize base cases (leaf nodes of game tree)
        for m_r in range(rows):
            for m_c in range(cols):
                if grid[m_r][m_c] == '#': continue
                for c_r in range(rows):
                    for c_c in range(cols):
                        if grid[c_r][c_c] == '#': continue

                        for turn_idx in range(MAX_TURNS + 1):
                            # Mouse catches food
                            if (m_r, m_c) == food_pos:
                                for player_to_move in [0, 1]:
                                    if dp[(m_r, m_c, c_r, c_c, turn_idx, player_to_move)] == 0:
                                        dp[(m_r, m_c, c_r, c_c, turn_idx, player_to_move)] = 1 # Mouse wins
                                        q.append(((m_r, m_c, c_r, c_c, turn_idx, player_to_move)))

                            # Cat catches Mouse or Cat catches food
                            # Note: If Mouse is on food AND Cat is on Mouse/Food, Cat wins (Cat's conditions take precedence)
                            # This is because Cat winning conditions are checked first in the problem description.
                            # "Cat and Mouse share a cell", "Cat reaches the food" -> Cat wins.
                            # "Mouse reaches the food" -> Mouse wins.
                            # If (m_r, m_c) == food_pos AND (c_r, c_c) == (m_r, m_c), then Cat wins.
                            # If (m_r, m_c) == food_pos AND (c_r, c_c) == food_pos, then Cat wins.
                            # So, if Cat's winning conditions are met, Cat wins.
                            if (c_r, c_c) == (m_r, m_c) or (c_r, c_c) == food_pos:
                                for player_to_move in [0, 1]:
                                    # Only update if not already determined as Mouse win (which would be incorrect precedence)
                                    # Or if it was already determined as Mouse win, overwrite it to Cat win.
                                    if dp[(m_r, m_c, c_r, c_c, turn_idx, player_to_move)] != 2:
                                        dp[(m_r, m_c, c_r, c_c, turn_idx, player_to_move)] = 2 # Cat wins
                                        q.append(((m_r, m_c, c_r, c_c, turn_idx, player_to_move)))

                            # Max turn states are Cat wins (Draw)
                            # This must be checked AFTER other win conditions, as a win can happen on turn 999.
                            # Only if no other win condition is met, and turn_idx reaches MAX_TURNS, it's a draw.
                            if turn_idx == MAX_TURNS:
                                for player_to_move in [0, 1]:
                                    if dp[(m_r, m_c, c_r, c_c, turn_idx, player_to_move)] == 0:
                                        dp[(m_r, m_c, c_r, c_c, turn_idx, player_to_move)] = 2 # Cat wins (Draw)
                                        q.append(((m_r, m_c, c_r, c_c, turn_idx, player_to_move)))

        # Precompute valid moves and degree for each state
        # Degree is the count of subsequent states that are currently unknown (0)
        degrees = {}

        for m_r in range(rows):
            for m_c in range(cols):
                if grid[m_r][m_c] == '#': continue
                for c_r in range(rows):
                    for c_c in range(cols):
                        if grid[c_r][c_c] == '#': continue
                        for turn_idx in range(MAX_TURNS): # turn_idx up to MAX_TURNS-1, as MAX_TURNS is already handled

                            # Mouse's turn (player_to_move = 0)
                            curr_state_mouse_turn = (m_r, m_c, c_r, c_c, turn_idx, 0)
                            if dp[curr_state_mouse_turn] == 0:
                                current_degree = 0
                                # Mouse moves: staying in place
                                current_degree += 1 # Always one move to stay in place
                                # Mouse moves: jumping
                                for i in range(4):
                                    for jump in range(1, mouseJump + 1):
                                        new_m_r, new_m_c = m_r + dr[i] * jump, m_c + dc[i] * jump
                                        if not (0 <= new_m_r < rows and 0 <= new_m_c < cols and grid[new_m_r][new_m_c] != '#'):
                                            break # Hit wall or out of bounds, stop jumping in this direction
                                        current_degree += 1
                                degrees[curr_state_mouse_turn] = current_degree

                            # Cat's turn (player_to_move = 1)
                            curr_state_cat_turn = (m_r, m_c, c_r, c_c, turn_idx, 1)
                            if dp[curr_state_cat_turn] == 0:
                                current_degree = 0
                                # Cat moves: staying in place
                                current_degree += 1 # Always one move to stay in place
                                # Cat moves: jumping
                                for i in range(4):
                                    for jump in range(1, catJump + 1):
                                        new_c_r, new_c_c = c_r + dr[i] * jump, c_c + dc[i] * jump
                                        if not (0 <= new_c_r < rows and 0 <= new_c_c < cols and grid[new_c_r][new_c_c] != '#'):
                                            break # Hit wall or out of bounds
                                        current_degree += 1
                                degrees[curr_state_cat_turn] = current_degree


        # BFS to propagate outcomes
        while q:
            (m_r, m_c, c_r, c_c, turn_idx, player_who_moved) = q.popleft()
            outcome = dp[(m_r, m_c, c_r, c_c, turn_idx, player_who_moved)]

            # If player_who_moved was 0 (Mouse moved), then we are processing a state
            # (m_r, m_c, c_r, c_c, turn_idx, 1) which is Cat's turn.
            # We need to find previous states (m_prev_r, m_prev_c, c_r, c_c, turn_idx, 0)
            # from which Mouse could have moved to (m_r, m_c).
            if player_who_moved == 1: # Cat just moved to (c_r, c_c). The current state in queue is (m_r, c_r, c_c, turn_idx, 1)
                                      # This means it was Cat's turn at (turn_idx-1) and Cat moved to (c_r, c_c).
                                      # The outcome is for the state (m_r, m_c, c_r, c_c, turn_idx, 0) which is Mouse's turn.
                                      # We need to find states (m_r, m_c, c_prev_r, c_prev_c, turn_idx - 1, 1)
                                      # from which Cat could have moved to (c_r, c_c).

                if turn_idx == 0: continue # Cannot go back in turns if turn_idx is 0

                # Cat stayed in place to reach (c_r, c_c)
                prev_cat_state = (m_r, m_c, c_r, c_c, turn_idx - 1, 1)
                if dp[prev_cat_state] == 0: # If this state's outcome is not yet determined
                    if outcome == 2: # Cat wins from the next state (m_r, m_c, c_r, c_c, turn_idx, 0)
                                     # This means Cat made a winning move to reach (c_r, c_c).
                        dp[prev_cat_state] = 2 # Cat can force a win from prev_cat_state
                        q.append(prev_cat_state)
                    elif outcome == 1: # Mouse wins from the next state
                                       # This means Cat made a losing move. Decrement degree.
                        degrees[prev_cat_state] -= 1
                        if degrees[prev_cat_state] == 0: # All moves lead to Mouse win
                            dp[prev_cat_state] = 1 # Cat loses => Mouse wins
                            q.append(prev_cat_state)

                # Cat jumped to reach (c_r, c_c)
                for i in range(4):
                    for jump in range(1, catJump + 1):
                        c_prev_r, c_prev_c = c_r - dr[i] * jump, c_c - dc[i] * jump
                        if not (0 <= c_prev_r < rows and 0 <= c_prev_c < cols and grid[c_prev_r][c_prev_c] != '#'):
                            break # Hit wall or out of bounds, stop jumping in this direction

                        prev_cat_state = (m_r, m_c, c_prev_r, c_prev_c, turn_idx - 1, 1)
                        if dp[prev_cat_state] == 0:
                            if outcome == 2: # Cat wins from next state
                                dp[prev_cat_state] = 2 # Cat can force a win
                                q.append(prev_cat_state)
                            elif outcome == 1: # Mouse wins from next state
                                degrees[prev_cat_state] -= 1
                                if degrees[prev_cat_state] == 0:
                                    dp[prev_cat_state] = 1 # Cat loses => Mouse wins
                                    q.append(prev_cat_state)

            elif player_who_moved == 0: # Mouse just moved to (m_r, m_c). The current state in queue is (m_r, m_c, c_r, c_c, turn_idx, 0)
                                        # This means it was Mouse's turn at (turn_idx) and Mouse moved to (m_r, m_c).
                                        # The outcome is for the state (m_r, m_c, c_r, c_c, turn_idx, 1) which is Cat's turn.
                                        # We need to find states (m_prev_r, m_prev_c, c_r, c_c, turn_idx, 0)
                                        # from which Mouse could have moved to (m_r, m_c).

                # Mouse stayed in place to reach (m_r, m_c)
                prev_mouse_state = (m_r, m_c, c_r, c_c, turn_idx, 0)
                if dp[prev_mouse_state] == 0:
                    if outcome == 1: # Mouse wins from next state (m_r, m_c, c_r, c_c, turn_idx, 1)
                                     # This means Mouse made a winning move to reach (m_r, m_c).
                        dp[prev_mouse_state] = 1 # Mouse can force a win
                        q.append(prev_mouse_state)
                    elif outcome == 2: # Cat wins from next state
                                       # This means Mouse made a losing move. Decrement degree.
                        degrees[prev_mouse_state] -= 1
                        if degrees[prev_mouse_state] == 0: # All moves lead to Cat win
                            dp[prev_mouse_state] = 2 # Mouse loses => Cat wins
                            q.append(prev_mouse_state)

                # Mouse jumped to reach (m_r, m_c)
                for i in range(4):
                    for jump in range(1, mouseJump + 1):
                        m_prev_r, m_prev_c = m_r - dr[i] * jump, m_c - dc[i] * jump
                        if not (0 <= m_prev_r < rows and 0 <= m_prev_c < cols and grid[m_prev_r][m_prev_c] != '#'):
                            break

                        prev_mouse_state = (m_prev_r, m_prev_c, c_r, c_c, turn_idx, 0)
                        if dp[prev_mouse_state] == 0:
                            if outcome == 1: # Mouse wins from next state
                                dp[prev_mouse_state] = 1 # Mouse can force a win
                                q.append(prev_mouse_state)
                            elif outcome == 2: # Cat wins from next state
                                degrees[prev_mouse_state] -= 1
                                if degrees[prev_mouse_state] == 0:
                                    dp[prev_mouse_state] = 2 # Mouse loses => Cat wins
                                    q.append(prev_mouse_state)

        # The initial state is (mouse_start_r, mouse_start_c, cat_start_r, cat_start_c, 0, 0)
        # Mouse moves first, turn_idx = 0
        return dp[(mouse_start[0], mouse_start[1], cat_start[0], cat_start[1], 0, 0)] == 1

