import collections
from typing import List

class Solution:
    def canMouseWin(self, grid: List[str], catJump: int, mouseJump: int) -> bool:
        rows, cols = len(grid), len(grid[0])

        # Find initial positions of Cat, Mouse, and Food
        mouse_start = (-1, -1)
        cat_start = (-1, -1)
        food_pos = (-1, -1)

        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == 'M':
                    mouse_start = (r, c)
                elif grid[r][c] == 'C':
                    cat_start = (r, c)
                elif grid[r][c] == 'F':
                    food_pos = (r, c)

        # Directions for movement
        dr = [-1, 1, 0, 0]
        dc = [0, 0, -1, 1]

