                                          # if the game goes on for 1000 moves (turn_idx 0 to 999), and no one has won, Cat wins.
                                          # So, if turn_idx == 1000, Cat wins.

        # DP state: (mouse_r, mouse_c, cat_r, cat_c, turn_idx, player_to_move)
        # player_to_move: 0 for Mouse, 1 for Cat
        # Values:
        # 0: Unknown/Draw (default)
        # 1: Mouse wins
        # 2: Cat wins
        dp = collections.defaultdict(int)

        # Degrees for each state (m_r, m_c, c_r, c_c, turn_idx, player_to_move)
        # This will store how many moves from this state lead to an unknown outcome.
        # When a state's outcome is determined, we update its predecessors.
        # If a player can move to a state where they win, they take it.
        # If all moves lead to states where they lose, then they lose.
        degrees = {}

