# Candidate 4
import collections
from typing import List

class Solution:
    def canMouseWin(self, grid: List[str], catJump: int, mouseJump: int) -> bool:
        rows, cols = len(grid), len(grid[0])

        # Find initial positions of Cat, Mouse, and Food
        mouse_start = (-1, -1)
        cat_start = (-1, -1)
        food_pos = (-1, -1)

        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == 'M':
                    mouse_start = (r, c)
                elif grid[r][c] == 'C':
                    cat_start = (r, c)
                elif grid[r][c] == 'F':
                    food_pos = (r, c)

        # Directions for movement
        dr = [-1, 1, 0, 0]
        dc = [0, 0, -1, 1]

        # Max turns for the game to end in a draw (Cat wins)
        # The problem states 1000 turns. A turn consists of one player's move.
        # So, turn_idx can go from 0 to 999. If turn_idx reaches 1000, it's a draw (Cat wins).
        # The state (m_r, m_c, c_r, c_c, turn_idx, player_to_move) means it's player_to_move's turn at turn_idx.
        # If turn_idx == 1000, it's a draw.
        MAX_TURNS = 1000

        # DP state: (mouse_r, mouse_c, cat_r, cat_c, turn_idx, player_to_move)
        # player_to_move: 0 for Mouse, 1 for Cat
        # Values:
        # 0: Unknown (default)
        # 1: Mouse wins
        # 2: Cat wins
        dp = collections.defaultdict(int) # Default value 0 (Unknown)

        # Degrees for each state (m_r, m_c, c_r, c_c, turn_idx, player_to_move)
        # This will store how many moves from this state lead to an unknown outcome.
        # For Mouse (player 0): Mouse wins if any move leads to a state where Mouse wins.
        # For Cat (player 1): Cat wins if any move leads to a state where Cat wins.
        # If a player cannot win, they try to draw. If they cannot draw, they lose.
        # In this problem, a draw is a Cat win. So, Mouse wants to win, Cat wants to win or draw.
        # Mouse wins (1), Cat wins (2).
        # For Mouse: if any next state is 1, current state is 1. Else, if all next states are 2, current state is 2. Else, 0.
        # For Cat: if any next state is 2, current state is 2. Else, if all next states are 1, current state is 1. Else, 0.

        # We'll use a queue for a BFS-like approach (backward DP)
        # The queue will store states whose outcome has been determined.
        q = collections.deque()

        # Initialize base cases (leaf nodes of game tree)
        for m_r in range(rows):
            for m_c in range(cols):
                if grid[m_r][m_c] == '#': continue
                for c_r in range(rows):
                    for c_c in range(cols):
                        if grid[c_r][c_c] == '#': continue

                        for turn_idx in range(MAX_TURNS + 1):
                            # Mouse catches food
                            if (m_r, m_c) == food_pos:
                                if dp[(m_r, m_c, c_r, c_c, turn_idx, 0)] == 0:
                                    dp[(m_r, m_c, c_r, c_c, turn_idx, 0)] = 1 # Mouse wins
                                    q.append(((m_r, m_c, c_r, c_c, turn_idx, 0)))
                                if dp[(m_r, m_c, c_r, c_c, turn_idx, 1)] == 0:
                                    dp[(m_r, m_c, c_r, c_c, turn_idx, 1)] = 1 # Mouse wins
                                    q.append(((m_r, m_c, c_r, c_c, turn_idx, 1)))

                            # Cat catches Mouse or Cat catches food
                            # Note: If mouse is on food and cat is on mouse, mouse wins (food first).
                            # The problem states "Mouse wins only by reaching the food first."
                            # "Victory conditions for the Cat include: reaching the food first, occupying the same square as the Mouse"
                            # This implies if Mouse reaches food, Mouse wins. If Cat reaches food, Cat wins.
                            # If Cat is on food and Mouse is not, Cat wins.
                            # If Mouse is on food and Cat is not, Mouse wins.
                            # If both are on food, and it's Mouse's turn, Mouse wins.
                            # If both are on food, and it's Cat's turn, Mouse wins (Mouse already there).
                            # The order of checks matters. Mouse reaching food is highest priority for Mouse.
                            # If (m_r, m_c) == food_pos, Mouse wins. This is handled above.
                            # So, if we reach here, (m_r, m_c) != food_pos.
                            if (c_r, c_c) == (m_r, m_c) or (c_r, c_c) == food_pos:
                                if dp[(m_r, m_c, c_r, c_c, turn_idx, 0)] == 0:
                                    dp[(m_r, m_c, c_r, c_c, turn_idx, 0)] = 2 # Cat wins
                                    q.append(((m_r, m_c, c_r, c_c, turn_idx, 0)))
                                if dp[(m_r, m_c, c_r, c_c, turn_idx, 1)] == 0:
                                    dp[(m_r, m_c, c_r, c_c, turn_idx, 1)] = 2 # Cat wins
                                    q.append(((m_r, m_c, c_r, c_c, turn_idx, 1)))

                            # Max turn states are Cat wins (Draw)
                            # This applies if no other win condition was met by MAX_TURNS.
                            # If turn_idx == MAX_TURNS, it's a draw (Cat wins).
                            # This should be checked last, or ensure it doesn't override a win.
                            # Since we only add if dp[state] == 0, it's fine.
                            if turn_idx == MAX_TURNS:
                                if dp[(m_r, m_c, c_r, c_c, turn_idx, 0)] == 0:
                                    dp[(m_r, m_c, c_r, c_c, turn_idx, 0)] = 2 # Cat wins
                                    q.append(((m_r, m_c, c_r, c_c, turn_idx, 0)))
                                if dp[(m_r, m_c, c_r, c_c, turn_idx, 1)] == 0:
                                    dp[(m_r, m_c, c_r, c_c, turn_idx, 1)] = 2 # Cat wins
                                    q.append(((m_r, m_c, c_r, c_c, turn_idx, 1)))

        # Precompute valid moves and degree for each state
        # Degree is the count of subsequent states that are currently unknown (0)
        # This is for states that are not yet determined (dp[state] == 0)
        degrees = collections.defaultdict(int)

        for m_r in range(rows):
            for m_c in range(cols):
                if grid[m_r][m_c] == '#': continue
                for c_r in range(rows):
                    for c_c in range(cols):
                        if grid[c_r][c_c] == '#': continue
                        for turn_idx in range(MAX_TURNS): # turn_idx up to MAX_TURNS-1, MAX_TURNS handled as base case

                            # Mouse's turn (player_to_move = 0)
                            curr_state_mouse_turn = (m_r, m_c, c_r, c_c, turn_idx, 0)
                            if dp[curr_state_mouse_turn] == 0:
                                # Mouse can stay put
                                degrees[curr_state_mouse_turn] += 1
                                # Mouse can jump
                                for i in range(4):
                                    for jump in range(1, mouseJump + 1):
                                        new_m_r, new_m_c = m_r + dr[i] * jump, m_c + dc[i] * jump
                                        if not (0 <= new_m_r < rows and 0 <= new_m_c < cols and grid[new_m_r][new_m_c] != '#'):
                                            break # Hit wall or out of bounds, stop jumping in this direction
                                        degrees[curr_state_mouse_turn] += 1

                            # Cat's turn (player_to_move = 1)
                            curr_state_cat_turn = (m_r, m_c, c_r, c_c, turn_idx, 1)
                            if dp[curr_state_cat_turn] == 0:
                                # Cat can stay put
                                degrees[curr_state_cat_turn] += 1
                                # Cat can jump
                                for i in range(4):
                                    for jump in range(1, catJump + 1):
                                        new_c_r, new_c_c = c_r + dr[i] * jump, c_c + dc[i] * jump
                                        if not (0 <= new_c_r < rows and 0 <= new_c_c < cols and grid[new_c_r][new_c_c] != '#'):
                                            break # Hit wall or out of bounds
                                        degrees[curr_state_cat_turn] += 1

        # BFS to propagate outcomes
        while q:
            (m_r, m_c, c_r, c_c, turn_idx, player_to_move) = q.popleft()
            outcome = dp[(m_r, m_c, c_r, c_c, turn_idx, player_to_move)]

            # If it was Mouse's turn (player_to_move = 0), then Cat moved to reach this state.
            # We need to update states where Cat moved from (c_prev_r, c_prev_c) to (c_r, c_c)
            # at turn_idx - 1, and it was Cat's turn.
            if player_to_move == 0: # It's Mouse's turn at turn_idx. Cat moved at turn_idx-1.
                if turn_idx == 0: continue # Cannot go back in turns if turn_idx is 0

                # Cat stayed in place to reach (c_r, c_c)
                prev_cat_state = (m_r, m_c, c_r, c_c, turn_idx - 1, 1)
                if dp[prev_cat_state] == 0: # If this state's outcome is not yet determined
                    if outcome == 2: # Cat wins from (m_r, m_c, c_r, c_c, turn_idx, 0)
                                     # This means Cat made a good move to (c_r, c_c) from (c_r, c_c)
                        dp[prev_cat_state] = 2 # Cat can force a win by moving to this state
                        q.append(prev_cat_state)
                    else: # outcome == 1 (Mouse wins from next state)
                          # This means Cat made a bad move. Decrement degree.
                        degrees[prev_cat_state] -= 1
                        if degrees[prev_cat_state] == 0: # All Cat's moves lead to Mouse win
                            dp[prev_cat_state] = 1 # Cat loses => Mouse wins
                            q.append(prev_cat_state)

                # Cat jumped to reach (c_r, c_c)
                for i in range(4):
                    for jump in range(1, catJump + 1):
                        c_prev_r, c_prev_c = c_r - dr[i] * jump, c_c - dc[i] * jump
                        if not (0 <= c_prev_r < rows and 0 <= c_prev_c < cols and grid[c_prev_r][c_prev_c] != '#'):
                            break # Hit wall or out of bounds, stop jumping in this direction

                        prev_cat_state = (m_r, m_c, c_prev_r, c_prev_c, turn_idx - 1, 1)
                        if dp[prev_cat_state] == 0:
                            if outcome == 2: # Cat wins from (m_r, m_c, c_r, c_c, turn_idx, 0)
                                dp[prev_cat_state] = 2 # Cat can force a win
                                q.append(prev_cat_state)
                            else: # outcome == 1 (Mouse wins from next state)
                                degrees[prev_cat_state] -= 1
                                if degrees[prev_cat_state] == 0:
                                    dp[prev_cat_state] = 1 # Cat loses => Mouse wins
                                    q.append(prev_cat_state)

            # If it was Cat's turn (player_to_move = 1), then Mouse moved to reach this state.
            # We need to update states where Mouse moved from (m_prev_r, m_prev_c) to (m_r, m_c)
            # at turn_idx, and it was Mouse's turn.
            elif player_to_move == 1: # It's Cat's turn at turn_idx. Mouse moved at turn_idx.

                # Mouse stayed in place to reach (m_r, m_c)
                prev_mouse_state = (m_r, m_c, c_r, c_c, turn_idx, 0)
                if dp[prev_mouse_state] == 0:
                    if outcome == 1: # Mouse wins from (m_r, m_c, c_r, c_c, turn_idx, 1)
                                     # This means Mouse made a good move to (m_r, m_c) from (m_r, m_c)
                        dp[prev_mouse_state] = 1 # Mouse can force a win
                        q.append(prev_mouse_state)
                    else: # outcome == 2 (Cat wins from next state)
                          # This means Mouse made a bad move. Decrement degree.
                        degrees[prev_mouse_state] -= 1
                        if degrees[prev_mouse_state] == 0: # All Mouse's moves lead to Cat win
                            dp[prev_mouse_state] = 2 # Mouse loses => Cat wins
                            q.append(prev_mouse_state)

                # Mouse jumped to reach (m_r, m_c)
                for i in range(4):
                    for jump in range(1, mouseJump + 1):
                        m_prev_r, m_prev_c = m_r - dr[i] * jump, m_c - dc[i] * jump
                        if not (0 <= m_prev_r < rows and 0 <= m_prev_c < cols and grid[m_prev_r][m_prev_c] != '#'):
                            break

                        prev_mouse_state = (m_prev_r, m_prev_c, c_r, c_c, turn_idx, 0)
                        if dp[prev_mouse_state] == 0:
                            if outcome == 1: # Mouse wins from (m_r, m_c, c_r, c_c, turn_idx, 1)
                                dp[prev_mouse_state] = 1 # Mouse can force a win
                                q.append(prev_mouse_state)
                            else: # outcome == 2 (Cat wins from next state)
                                degrees[prev_mouse_state] -= 1
                                if degrees[prev_mouse_state] == 0:
                                    dp[prev_mouse_state] = 2 # Mouse loses => Cat wins
                                    q.append(prev_mouse_state)

        # The initial state is (mouse_start_r, mouse_start_c, cat_start_r, cat_start_c, 0, 0)
        # Mouse moves first, turn_idx = 0
        return dp[(mouse_start[0], mouse_start[1], cat_start[0], cat_start[1], 0, 0)] == 1

