import collections
from typing import List

class Solution:
    def canMouseWin(self, grid: List[str], catJump: int, mouseJump: int) -> bool:
        rows, cols = len(grid), len(grid[0])

        # Find initial positions of Cat, Mouse, and Food
        mouse_start = (-1, -1)
        cat_start = (-1, -1)
        food_pos = (-1, -1)

        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == 'M':
                    mouse_start = (r, c)
                elif grid[r][c] == 'C':
                    cat_start = (r, c)
                elif grid[r][c] == 'F':
                    food_pos = (r, c)

        # Directions for movement
        dr = [-1, 1, 0, 0]
        dc = [0, 0, -1, 1]

        # Max turns for the game to end in a draw (Cat wins)
        # A state is (mouse_pos, cat_pos, turn_idx, player_to_move).
        # (rows*cols)^2 * 2 states.
        # Max turns = 1000. Each turn is one player's move.
        # So, 500 rounds (Mouse moves, then Cat moves).
        # If the game doesn't end in 1000 turns, Cat wins.
        # The turn_idx goes from 0 to 999.
        # If turn_idx reaches 1000, it means 1000 moves have been made.
        # The problem states "within 1000 turns". This usually means 1000 moves.
        # So, if turn_idx == 1000, Cat wins.
        MAX_TURNS = 1000

        # DP state: (mouse_r, mouse_c, cat_r, cat_c, turn_idx, player_to_move)
        # player_to_move: 0 for Mouse, 1 for Cat
        # Values:
        # 0: Unknown (default)
        # 1: Mouse wins
        # 2: Cat wins
        dp = collections.defaultdict(int)

        # Degrees for each state (m_r, m_c, c_r, c_c, turn_idx, player_to_move)
        # This will store how many moves from this state lead to an unknown outcome.
        # For Mouse: if Mouse can move to a state where Mouse wins, Mouse wins from current state.
        #            If all moves lead to states where Cat wins, Mouse loses from current state.
        # For Cat:   if Cat can move to a state where Cat wins, Cat wins from current state.
        #            If all moves lead to states where Mouse wins, Cat loses from current state.
        degrees = {}

        # Queue for BFS-like approach (backward DP)
        q = collections.deque()

        # Precompute degrees and initialize base cases (leaf nodes of game tree)
        for m_r in range(rows):
            for m_c in range(cols):
                if grid[m_r][m_c] == '#': continue
                for c_r in range(rows):
                    for c_c in range(cols):
                        if grid[c_r][c_c] == '#': continue

                        # Cat cannot be on the same cell as Mouse if Mouse is on food.
                        # If Cat is on food, Cat wins.
                        # If Mouse is on food, Mouse wins.
                        # If Cat is on Mouse, Cat wins.
                        # The problem states "Mouse can jump over the Cat".
                        # This implies that Mouse can land on Cat's cell.
                        # If Mouse lands on Cat's cell, Cat wins.
                        # If Cat lands on Mouse's cell, Cat wins.
                        # If Cat and Mouse are on the same cell, Cat wins.

                        # Base cases for all turn_idx and player_to_move
                        for turn_idx in range(MAX_TURNS + 1):
                            for player_to_move in [0, 1]:
                                state = (m_r, m_c, c_r, c_c, turn_idx, player_to_move)

                                # Cat wins conditions
                                if (c_r, c_c) == food_pos or (c_r, c_c) == (m_r, m_c):
                                    if dp[state] == 0:
                                        dp[state] = 2 # Cat wins
                                        q.append(state)
                                # Mouse wins conditions
                                elif (m_r, m_c) == food_pos:
                                    if dp[state] == 0:
                                        dp[state] = 1 # Mouse wins
                                        q.append(state)
                                # Max turns reached (Cat wins by draw)
                                elif turn_idx == MAX_TURNS:
                                    if dp[state] == 0:
                                        dp[state] = 2 # Cat wins (draw)
                                        q.append(state)

        # Calculate degrees for all states that are not yet determined
        for m_r in range(rows):
            for m_c in range(cols):
                if grid[m_r][m_c] == '#': continue
                for c_r in range(rows):
                    for c_c in range(cols):
                        if grid[c_r][c_c] == '#': continue
                        for turn_idx in range(MAX_TURNS): # turn_idx up to MAX_TURNS-1

                            # Mouse's turn (player_to_move = 0)
                            curr_state_mouse_turn = (m_r, m_c, c_r, c_c, turn_idx, 0)
                            if dp[curr_state_mouse_turn] == 0:
                                current_degree = 0
                                # Mouse staying in place
                                # Next state is (m_r, m_c, c_r, c_c, turn_idx, 1) (Cat's turn)
                                if dp[(m_r, m_c, c_r, c_c, turn_idx, 1)] == 0:
                                    current_degree += 1
                                # Mouse jumping
                                for i in range(4):
                                    for jump in range(1, mouseJump + 1):
                                        new_m_r, new_m_c = m_r + dr[i] * jump, m_c + dc[i] * jump
                                        if not (0 <= new_m_r < rows and 0 <= new_m_c < cols and grid[new_m_r][new_m_c] != '#'):
                                            break # Hit wall or out of bounds, stop jumping in this direction
                                        # Next state is (new_m_r, new_m_c, c_r, c_c, turn_idx, 1) (Cat's turn)
                                        if dp[(new_m_r, new_m_c, c_r, c_c, turn_idx, 1)] == 0:
                                            current_degree += 1
                                degrees[curr_state_mouse_turn] = current_degree

                            # Cat's turn (player_to_move = 1)
                            curr_state_cat_turn = (m_r, m_c, c_r, c_c, turn_idx, 1)
                            if dp[curr_state_cat_turn] == 0:
                                current_degree = 0
                                # Cat staying in place
                                # Next state is (m_r, c_r, c_c, turn_idx + 1, 0) (Mouse's turn)
                                if dp[(m_r, m_c, c_r, c_c, turn_idx + 1, 0)] == 0:
                                    current_degree += 1
                                # Cat jumping
                                for i in range(4):
                                    for jump in range(1, catJump + 1):
                                        new_c_r, new_c_c = c_r + dr[i] * jump, c_c + dc[i] * jump
                                        if not (0 <= new_c_r < rows and 0 <= new_c_c < cols and grid[new_c_r][new_c_c] != '#'):
                                            break # Hit wall or out of bounds
                                        # Next state is (m_r, m_c, new_c_r, new_c_c, turn_idx + 1, 0) (Mouse's turn)
                                        if dp[(m_r, m_c, new_c_r, new_c_c, turn_idx + 1, 0)] == 0:
                                            current_degree += 1
                                degrees[curr_state_cat_turn] = current_degree

        # BFS to propagate outcomes
        while q:
            (m_r, m_c, c_r, c_c, turn_idx, player_who_is_about_to_move) = q.popleft()
            outcome = dp[(m_r, m_c, c_r, c_c, turn_idx, player_who_is_about_to_move)]

            # If it was Mouse's turn (player_who_is_about_to_move = 0),
            # then Mouse moved from some (m_prev_r, m_prev_c) to (m_r, m_c)
            # and now it's Cat's turn (player_who_is_about_to_move = 1) at the same turn_idx.
            # The state in the queue is (m_r, m_c, c_r, c_c, turn_idx, player_who_is_about_to_move).
            # This means the outcome is for the player whose turn it is.
            # So, if player_who_is_about_to_move is 0, it's Mouse's turn.
            # If player_who_is_about_to_move is 1, it's Cat's turn.

            # We need to find the *previous* states that could lead to the current state.
            # If current state is (m_r, m_c, c_r, c_c, turn_idx, 0) (Mouse's turn),
            # it means Cat just moved from (c_prev_r, c_prev_c) to (c_r, c_c) at turn_idx-1.
            # So, we look for states (m_r, m_c, c_prev_r, c_prev_c, turn_idx - 1, 1)
            if player_who_is_about_to_move == 0: # It's Mouse's turn. Cat just moved to (c_r, c_c) at turn_idx-1.
