                    prev_cat_state = (m_r, m_c, c_r, c_c, turn_idx - 1, 1)
                    if dp[prev_cat_state] == 0:
                        if outcome == 2: # If Cat wins from current state, then Cat can force a win by moving to (c_r, c_c)
                            dp[prev_cat_state] = 2
                            q.append(prev_cat_state)
                        elif outcome == 1: # If Mouse wins from current state, then Cat moving to (c_r, c_c) is a bad move for Cat.
                            degrees[prev_cat_state] -= 1
                            if degrees[prev_cat_state] == 0: # All Cat's moves lead to Mouse winning
                                dp[prev_cat_state] = 1 # Cat loses => Mouse wins
                                q.append(prev_cat_state)

                    # Cat jumped to reach (c_r, c_c)
                    for i in range(4):
                        for jump in range(1, catJump + 1):
                            c_prev_r, c_prev_c = c_r - dr[i] * jump, c_c - dc[i] * jump
                            if not (0 <= c_prev_r < rows and 0 <= c_prev_c < cols and grid[c_prev_r][c_prev_c] != '#'):
                                break

                            prev_cat_state = (m_r, m_c, c_prev_r, c_prev_c, turn_idx - 1, 1)
                            if dp[prev_cat_state] == 0:
                                if outcome == 2: # Cat wins
                                    dp[prev_cat_state] = 2
                                    q.append(prev_cat_state)
                                elif outcome == 1: # Mouse wins
                                    degrees[prev_cat_state] -= 1
                                    if degrees[prev_cat_state] == 0:
                                        dp[prev_cat_state] = 1
                                        q.append(prev_cat_state)

            # If current state is (m_r, m_c, c_r, c_c, turn_idx, 1) (Cat's turn),
            # it means Mouse just moved from (m_prev_r, m_prev_c) to (m_r, m_c) at turn_idx.
            # So, we look for states (m_prev_r, m_prev_c, c_r, c_c, turn_idx, 0)
            elif player_who_is_about_to_move == 1: # It's Cat's turn. Mouse just moved to (m_r, m_c) at turn_idx.
                # Mouse stayed in place to reach (m_r, m_c)
                prev_mouse_state = (m_r, m_c, c_r, c_c, turn_idx, 0)
                if dp[prev_mouse_state] == 0:
                    if outcome == 1: # If Mouse wins from current state, then Mouse can force a win by moving to (m_r, m_c)
                        dp[prev_mouse_state] = 1
                        q.append(prev_mouse_state)
                    elif outcome == 2: # If Cat wins from current state, then Mouse moving to (m_r, m_c) is a bad move for Mouse.
                        degrees[prev_mouse_state] -= 1
                        if degrees[prev_mouse_state] == 0: # All Mouse's moves lead to Cat winning
                            dp[prev_mouse_state] = 2 # Mouse loses => Cat wins
                            q.append(prev_mouse_state)

                # Mouse jumped to reach (m_r, m_c)
                for i in range(4):
                    for jump in range(1, mouseJump + 1):
                        m_prev_r, m_prev_c = m_r - dr[i] * jump, m_c - dc[i] * jump
                        if not (0 <= m_prev_r < rows and 0 <= m_prev_c < cols and grid[m_prev_r][m_prev_c] != '#'):
                            break

                        prev_mouse_state = (m_prev_r, m_prev_c, c_r, c_c, turn_idx, 0)
                        if dp[prev_mouse_state] == 0:
                            if outcome == 1: # Mouse wins
