                    for i in range(4):
                        for jump in range(1, catJump + 1):
                            c_prev_r, c_prev_c = c_r - dr[i] * jump, c_c - dc[i] * jump
                            if not (0 <= c_prev_r < rows and 0 <= c_prev_c < cols and grid[c_prev_r][c_prev_c] != '#'):
                                break # Hit wall or out of bounds, stop jumping in this direction

                            prev_cat_state = (m_r, m_c, c_prev_r, c_prev_c, turn_idx - 1, 1)
                            if dp[prev_cat_state] == 0:
                                if outcome == 1: # If Cat moves from prev_cat_state to (m_r, m_c, c_r, c_c) and Mouse wins, it's a bad move for Cat.
                                    degrees[prev_cat_state] -= 1
                                    if degrees[prev_cat_state] == 0:
                                        dp[prev_cat_state] = 1 # Cat has no winning moves, all lead to Mouse win. Cat loses => Mouse wins.
                                        q.append(prev_cat_state)
                                elif outcome == 2: # If Cat moves from prev_cat_state to (m_r, m_c, c_r, c_c) and Cat wins, it's a good move for Cat.
                                    dp[prev_cat_state] = 2 # Cat can force a win by moving to this state
                                    q.append(prev_cat_state)

            elif player_who_moved == 0: # Mouse just made a move to (m_r, m_c), so current state is (m_r, m_c, c_r, c_c, turn_idx, 1)
                                        # The outcome is for Cat's turn.
                                        # We need to find states where Mouse moved FROM to get to (m_r, m_c).
                                        # So, we are looking for states (m_prev_r, m_prev_c, c_r, c_c, turn_idx, 0).

                # Mouse's previous state (m_prev_r, m_prev_c) that led to (m_r, m_c)
                # It was Mouse's turn at (turn_idx)
                # Mouse moved from (m_prev_r, m_prev_c) to (m_r, m_c)

                # Mouse stayed in place to reach (m_r, m_c)
                prev_mouse_state = (m_r, m_c, c_r, c_c, turn_idx, 0) # This refers to (m_r, m_c, c_r, c_c) being the state *before* Mouse moved
                if dp[prev_mouse_state] == 0:
                    if outcome == 1: # If Cat loses from this state (Mouse wins), then Mouse moving to this state is good for Mouse.
                        dp[prev_mouse_state] = 1 # Mouse can force a win
                        q.append(prev_mouse_state)
                    elif outcome == 2: # If Cat wins from this state (Mouse loses), then Mouse moving to this state is bad for Mouse.
                        degrees[prev_mouse_state] -= 1
                        if degrees[prev_mouse_state] == 0:
                            dp[prev_mouse_state] = 2 # Mouse has no winning moves, all lead to Cat win. Mouse loses => Cat wins.
                            q.append(prev_mouse_state)

                # Mouse jumped to reach (m_r, m_c)
                for i in range(4):
                    for jump in range(1, mouseJump + 1):
                        m_prev_r, m_prev_c = m_r - dr[i] * jump, m_c - dc[i] * jump
                        if not (0 <= m_prev_r < rows and 0 <= m_prev_c < cols and grid[m_prev_r][m_prev_c] != '#'):
                            break

                        prev_mouse_state = (m_prev_r, m_prev_c, c_r, c_c, turn_idx, 0)
                        if dp[prev_mouse_state] == 0:
                            if outcome == 1: # If Cat loses from this state (Mouse wins), then Mouse moving to this state is good for Mouse.
                                dp[prev_mouse_state] = 1 # Mouse can force a win
                                q.append(prev_mouse_state)
                            elif outcome == 2: # If Cat wins from this state (Mouse loses), then Mouse moving to this state is bad for Mouse.
                                degrees[prev_mouse_state] -= 1
                                if degrees[prev_mouse_state] == 0:
                                    dp[prev_mouse_state] = 2 # Mouse has no winning moves, all lead to Cat win. Mouse loses => Cat wins.
                                    q.append(prev_mouse_state)

        # The initial state is (mouse_start_r, mouse_start_c, cat_start_r, cat_start_c, 0, 0)
        # Mouse moves first, turn_idx = 0
        return dp[(mouse_start[0], mouse_start[1], cat_start[0], cat_start[1], 0, 0)] == 1

