from collections import defaultdict

class Solution:
    def groupStrings(self, words: list[str]) -> list[int]:
        n = len(words)

        # --- Disjoint Set Union (DSU) implementation ---
        parent = list(range(n))
        group_size = [1] * n

        def find(i):
            if parent[i] == i:
                return i
            parent[i] = find(parent[i])
            return parent[i]

        def union(i, j):
            root_i = find(i)
            root_j = find(j)
            if root_i != root_j:
                if group_size[root_i] < group_size[root_j]:
                    root_i, root_j = root_j, root_i
                parent[root_j] = root_i
                group_size[root_i] += group_size[root_j]
                return True
            return False
        # --- End DSU ---

        # To handle multiple words having the same bitmask, map bitmask to list of indices
        mask_to_indices = defaultdict(list)

        masks = []
        for i, word in enumerate(words):
            mask = 0
            for char in word:
                mask |= (1 << (ord(char) - ord('a')))
            masks.append(mask)
            mask_to_indices[mask].append(i)

        # Union all indices that share the exact same mask
        for mask in mask_to_indices:
            indices = mask_to_indices[mask]
            for i in range(1, len(indices)):
                union(indices[0], indices[i])

        # Connect masks that are one operation apart
        # Operation: 1 bit flip (add/remove) or 2 bit flips (swap/replace)
        processed_masks = list(mask_to_indices.keys())
        for mask in processed_masks:
            # Try removing one bit
            for j in range(26):
                if (mask >> j) & 1:
                    target = mask ^ (1 << j)
                    if target in mask_to_indices:
                        union(mask_to_indices[mask][0], mask_to_indices[target][0])

                    # Try replacing one bit (remove j, add k)
                    for k in range(26):
                        if not ((mask >> k) & 1):
                            target = (mask ^ (1 << j)) | (1 << k)
                            if target in mask_to_indices:
                                union(mask_to_indices[mask][0], mask_to_indices[target][0])

        num_groups = 0
        max_group_size = 0
        for i in range(n):
            if parent[i] == i:
                num_groups += 1
                max_group_size = max(max_group_size, group_size[i])

        return [num_groups, max_group_size]

