            if mask in mask_to_idx:
                union(i, mask_to_idx[mask])
            else:
                mask_to_idx[mask] = i

        # Process connections based on bitwise operations
        # Two words are connected if their masks differ by adding, deleting, or swapping a bit.
        # This is equivalent to saying:
        # 1. mask_a == mask_b (same)
        # 2. mask_a ^ mask_b == (1 << i) (add/delete)
        # 3. mask_a ^ mask_b == (1 << i) | (1 << j) (swap: remove bit i, add bit j)

        unique_masks = list(mask_to_idx.keys())
        for mask in unique_masks:
