                # Check swap changes (remove bit i, add bit j)
                if (mask >> i) & 1:
                    for j in range(26):
                        if not ((mask >> j) & 1):
                            neighbor_swap = (mask ^ (1 << i)) | (1 << j)
                            if neighbor_swap in mask_to_idx:
                                union(idx1, mask_to_idx[neighbor_swap])

        max_group_size = 0
        num_groups = 0

        for i in range(n):
            if parent[i] == i:
                num_groups += 1
                max_group_size = max(max_group_size, group_size[i])

        return [num_groups, max_group_size]

