from typing import List

class Solution:
    def optimalDivision(self, nums: List[int]) -> str:
        n = len(nums)

        if n == 1:
            return str(nums[0])
        if n == 2:
            return f"{nums[0]}/{nums[1]}"

        # To maximize a/b/c/d..., we should keep the first number as the numerator,
        # and treat all subsequent numbers as part of the denominator.
        # Mathematically, a / (b / c / d ...) = a * c * d * ... / b.
        # This is achieved by parenthesizing everything after the first slash.

        res = [str(nums[0]), "/("]
        res.append("/".join(map(str, nums[1:])))
        res.append(")")

        return "".join(res)

