        # Base case: if there are two numbers, no parentheses needed.
        if n == 2:
            return f"{nums[0]}/{nums[1]}"

        # For n > 2, the optimal strategy to maximize a/(b/c/d...) 
        # is to make the divisor as small as possible.
        # This is achieved by putting all elements after the first index 
        # into the denominator: nums[0] / (nums[1] / nums[2] / ... / nums[n-1])

        res = [str(nums[0]), "/("]
        for i in range(1, n):
