import collections
from typing import List

class Solution:
    def minOperations(self, nums: List[int], target: int) -> int:
        # The sum of elements remains invariant through the splitting process.
        # If the total sum is less than the target, no subsequence can sum to target.
        if sum(nums) < target:
            return -1

        # Count the occurrences of each power of 2.
        # Given nums[i] <= 2^30, we consider up to 2^30.
        counts = [0] * 32
        for x in nums:
            counts[x.bit_length() - 1] += 1

        operations = 0
        # We process bits from 0 upwards.
        for i in range(31):
            if (target >> i) & 1:
                # If we have the power, use it.
                if counts[i] > 0:
                    counts[i] -= 1
                else:
                    # Otherwise, find the smallest available power higher than 2^i
                    j = i + 1
                    while j < 32 and counts[j] == 0:
                        j += 1

                    if j == 32:
                        return -1

                    # Split the higher power down to 2^i
                    counts[j] -= 1
                    for k in range(j - 1, i - 1, -1):
                        counts[k] += 1
                        operations += 1
                    counts[i] -= 1 # Finally use the 2^i we created

            # Carry over excess counts to the next power
            counts[i + 1] += counts[i] // 2

        return operations

class Solution:
    def longestWord(self, words: list[str]) -> str:
        # Convert to a set for O(1) prefix lookups
        word_set = set(words)

        longest = ""

        for word in words:
            # A word is a candidate if all its prefixes exist in the set.
            # We check this by iterating through all prefixes.
            # To optimize, we only need to check prefixes up to len(word) - 1.
            # The word itself is in word_set by definition since it's in the input list.
            is_valid = True
            for i in range(1, len(word)):
                if word[:i] not in word_set:
                    is_valid = False
                    break

            if is_valid:
                # Update if:
                # 1. Current word is strictly longer
                # 2. Current word has the same length but is lexicographically smaller
                if len(word) > len(longest):
                    longest = word
                elif len(word) == len(longest):
                    if longest == "" or word < longest:
                        longest = word

        return longest

from typing import List

class Solution:
    def minimumRefill(self, plants: List[int], capacityA: int, capacityB: int) -> int:
        n = len(plants)
        current_water_A = capacityA
        current_water_B = capacityB
        refills = 0
        left = 0
        right = n - 1

        while left < right:
            # Alice's turn
            if current_water_A < plants[left]:
                refills += 1
                current_water_A = capacityA
            current_water_A -= plants[left]

            # Bob's turn
            if current_water_B < plants[right]:
                refills += 1
                current_water_B = capacityB
            current_water_B -= plants[right]

            left += 1
            right -= 1

        # If they meet at the same plant
        if left == right:
            if current_water_A >= current_water_B:
                if current_water_A < plants[left]:
                    refills += 1
            else:
                if current_water_B < plants[left]:
                    refills += 1

        return refills

class Solution:
    def splitLoopedString(self, strs: List[str]) -> str:
        # Pre-process: choose the lexicographically larger of s and reversed(s)
        # for all strings except the one we are currently "cutting".
        processed = []
        for s in strs:
            s_rev = s[::-1]
            if s >= s_rev:
                processed.append(s)
            else:
                processed.append(s_rev)

        max_str = ""

        # Iterate through each string, treating it as the one that contains the cut.
        for i in range(len(strs)):
            s = strs[i]
            s_rev = s[::-1]

            # The part of the loop that doesn't contain the cut string
            # consists of all other processed strings.
            other_parts = "".join(processed[:i] + processed[i+1:])

            # Try both orientations for the current string
            for part in [s, s_rev]:
                # Try all possible cut points in the current string
                for j in range(len(part)):
                    # The cut results in: (part[j:] + other_parts + part[:j])
                    candidate = part[j:] + other_parts + part[:j]
                    if candidate > max_str:
                        max_str = candidate

        return max_str

from collections import defaultdict
from typing import List

class Solution:
    def maximumSubtreeSize(self, edges: List[List[int]], colors: List[int]) -> int:
        n = len(colors)
        if n == 0:
            return 0
        if n == 1:
            return 1

        adj = defaultdict(list)
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)

        # parent_map and children to build the tree structure
        parent_map = {0: -1}
        children = defaultdict(list)
        order = []
        stack = [0]

        # Build tree using BFS/DFS to get traversal order
        while stack:
            u = stack.pop()
            order.append(u)
            for v in adj[u]:
                if v != parent_map[u]:
                    parent_map[v] = u
                    children[u].append(v)
                    stack.append(v)

        subtree_size = [1] * n
        is_uniform = [True] * n
        max_size = 1

        # Process in reverse topological order (bottom-up)
        for node in reversed(order):
            for child in children[node]:
                # Subtree is uniform if:
                # 1. Child subtree is uniform
                # 2. Child's color matches current node's color
                if not is_uniform[child] or colors[child] != colors[node]:
                    is_uniform[node] = False
                subtree_size[node] += subtree_size[child]

            if is_uniform[node]:
                max_size = max(max_size, subtree_size[node])

        return max_size

class Solution:
    def isMatch(self, s: str, p: str) -> bool:
        memo = {}

        def dp(i, j):
            if (i, j) in memo:
                return memo[(i, j)]

            # Base case: if pattern is exhausted
            if j == len(p):
                # If string is also exhausted, it's a match
                return i == len(s)

            # Check if the current characters match
            # This is true if s[i] exists and s[i] == p[j] or p[j] == '.'
            first_match = (i < len(s)) and (p[j] == s[i] or p[j] == '.')

            # Case 1: If the next character in pattern is '*'
            if j + 1 < len(p) and p[j + 1] == '*':
                # Option A: '*' matches zero occurrences of the preceding element p[j]
                # In this case, we skip p[j] and '*' and try to match s[i:] with p[j+2:]
                match_zero = dp(i, j + 2)

                # Option B: '*' matches one or more occurrences of the preceding element p[j]
                # This requires first_match to be true (s[i] matches p[j]).
                # If it matches, we try to match the rest of the string s[i+1:]
                # with the same pattern starting at j (as '*' allows repeats).
                match_one_or_more = first_match and dp(i + 1, j)

                # The result is true if either option A or option B is true
                memo[(i, j)] = match_zero or match_one_or_more
                return memo[(i, j)]
            # Case 2: If the next character is NOT '*'
            else:
                # If the current characters match, we advance both string and pattern
                memo[(i, j)] = first_match and dp(i + 1, j + 1)
                return memo[(i, j)]

        return dp(0, 0)
